// Limit every string scan by both its field size and the packet remainder.
static bool config_string(uint8_t *buffer, size_t capacity, int32_t *index,
		const char *value, size_t field_size) {
	const char *end = memchr(value, '\0', field_size);
	if (!end) return false;
	size_t count = (size_t)(end - value) + 1;
	if ((size_t)*index > capacity || count > capacity - (size_t)*index) return false;
	memcpy(buffer + *index, value, count);
	*index += (int32_t)count;
	return true;
}

static bool config_read_string(const uint8_t *buffer, size_t length, int32_t *index,
		char *value, size_t field_size) {
	if ((size_t)*index >= length) return false;
	size_t available = length - (size_t)*index;
	if (available > field_size) available = field_size;
	const uint8_t *start = buffer + *index;
	const uint8_t *end = memchr(start, '\0', available);
	if (!end) return false;
	size_t count = (size_t)(end - start) + 1;
	memcpy(value, start, count);
	*index += (int32_t)count;
	return true;
}

