	conf->wifi_mode = CONF_WIFI_MODE;
	_Static_assert(sizeof(CONF_WIFI_STA_SSID) <= sizeof(conf->wifi_sta_ssid), "CONF_WIFI_STA_SSID exceeds its configuration field");
	strcpy(conf->wifi_sta_ssid, CONF_WIFI_STA_SSID);
	_Static_assert(sizeof(CONF_WIFI_STA_KEY) <= sizeof(conf->wifi_sta_key), "CONF_WIFI_STA_KEY exceeds its configuration field");
	strcpy(conf->wifi_sta_key, CONF_WIFI_STA_KEY);
	_Static_assert(sizeof(CONF_WIFI_AP_SSID) <= sizeof(conf->wifi_ap_ssid), "CONF_WIFI_AP_SSID exceeds its configuration field");
